                    best = None
                    cand = [None] + [o for o in opts_by_day[sh.day] if o[1].id != sh.template.id]
                    for o in cand:
                        if o is not None:
                            day, tpl, segs, ivs, hours = o
                            if not self.can_take(a, day, tpl, segs, hours) or \
                                    self.total_hours() + hours > self.hour_budget + 1e-9:
                                continue
                            self.add(a, q, day, tpl, segs, ivs)
                        sc = self.queue_score(q)
                        if o is not None:
                            self.remove(self.by_agent[a.agent_id][-1])
                        if sc < score and (best is None or sc < best[0]):
                            best = (sc, o)
                    if best is None:
                        self.add(a, q, sh.day, sh.template, sh.segments, sh.intervals)
                    else:
                        score, o = best
                        if o is not None:
                            self.add(a, q, *o[:4])
                        changed = True
                # 2) add a shift for an agent with hours left
                for a in self.agents:
                    if q not in a.skills or time.monotonic() > deadline:
                        continue
                    best = None
                    for o in self.options:
                        day, tpl, segs, ivs, hours = o
                        if not self.can_take(a, day, tpl, segs, hours) or \
                                self.total_hours() + hours > self.hour_budget + 1e-9:
                            continue
                        self.add(a, q, day, tpl, segs, ivs)
                        sc = self.queue_score(q)
                        self.remove(self.by_agent[a.agent_id][-1])
                        if sc[0] < score[0] and (best is None or sc < best[0]):
                            best = (sc, o)
                    if best is not None:
                        score, o = best
                        self.add(a, q, *o[:4])
                        changed = True


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    w = _Week(req, cfg, agents, week)
    best = None
    for _ in range(MAX_ROUNDS):
        w.fill()
        short = w.shortfalls(w.place_breaks())
        score = len(short)
        if best is None or score < best[0]:
            best = (score, [(s.agent_id, s.queue, s.day, s.template, s.segments, s.intervals) for s in w.shifts])
        if not short:
            break
        raised = False
        for (q, t), gap in short.items():
            if w.extra[q][t] < 4:
                w.extra[q][t] += 1
                raised = True
        if not raised:
            break
    # restore the best round, then drop shifts that cover nothing short
    for sh in list(w.shifts):
        w.remove(sh)
    ids = {a.agent_id: a for a in w.agents}
    for aid, q, day, tpl, segs, ivs in best[1]:
        w.add(ids[aid], q, day, tpl, segs, ivs)
    w.prune()
    import time
    w.improve(time.monotonic() + float(cfg.get("search_seconds", 60)))
    w.place_breaks()
    return sorted(w.shifts, key=lambda s: (s.segments[0][0], s.agent_id))
"""Shift templates: local wall-clock segments on one local day; none crosses local midnight."""
from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


@dataclass(frozen=True)
class Template:
    id: str
    segments: tuple[tuple[int, int], ...]  # (start_hour, end_hour) local, end may be 24
    eligibility: str = "all"               # "all" or a contract code

    @property
    def hours(self) -> float:
        return float(sum(e - s for s, e in self.segments))

    @property
    def is_split(self) -> bool:
        return len(self.segments) > 1

    def segments_utc(self, day: date, tz: str) -> list[tuple[datetime, datetime]]:
        """Local wall-clock segments on `day` -> UTC datetimes."""
        z = ZoneInfo(tz)
        midnight = datetime(day.year, day.month, day.day, tzinfo=z)
        return [((midnight + timedelta(hours=s)).astimezone(timezone.utc),
                 (midnight + timedelta(hours=e)).astimezone(timezone.utc)) for s, e in self.segments]


TEMPLATES: list[Template] = [
    Template("E8", ((6, 14),)),
    Template("D8", ((9, 17),)),
    Template("L8", ((13, 21),)),
    Template("N8", ((16, 24),)),
    Template("P6a", ((7, 13),)),
    Template("P6b", ((15, 21),)),
    Template("P4", ((10, 14),)),
    Template("S44", ((8, 12), (16, 20)), eligibility="all"),
]


def client_templates(cfg: dict) -> list[Template]:
    """The service templates plus the client's own (`extra_templates`: a list of
    {id, segments: [[start_h, end_h], ...], eligibility}); local wall-clock, never past midnight."""
    extra = []
    for t in cfg.get("extra_templates") or []:
        segs = tuple((s, e) for s, e in t["segments"])
        if not all(0 <= s < e <= 24 for s, e in segs):
            raise SystemExit(f"template {t['id']}: segments must lie within one local day")
        extra.append(Template(t["id"], segs, t.get("eligibility", "all")))
    return TEMPLATES + extra


def templates_for(cfg: dict) -> list[Template]:
    """Templates that fit inside the client's local operating hours."""
    open_h, close_h = cfg["operating_hours"]
    return [t for t in client_templates(cfg) if all(open_h <= s and e <= close_h for s, e in t.segments)]


def eligible(template: Template, contract: str) -> bool:
    return template.eligibility == "all" or template.eligibility == contract
"""Evaluate a schedule.csv against the required curve: attainment, hours, constraint audit.

A convenience for engineers. Contractual evaluation is performed independently against each
client's SOW.
"""
from __future__ import annotations

from collections import defaultdict
from datetime import timedelta
from zoneinfo import ZoneInfo

import pandas as pd

from wfm import constraints
from wfm.roster import Agent


def _parse(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    for c in ("segment_start_utc", "segment_end_utc", "break_start_utc"):
        df[c] = pd.to_datetime(df[c], utc=True)
    df["break_minutes"] = df["break_minutes"].fillna(0).astype(int)
    return df


def coverage(sched: pd.DataFrame, grid, grain_min: int, skills: dict | None = None) -> tuple[dict, dict, dict]:
    """Per queue per interval: gross agents on queue, agents on break (overlapping the slot), and
    agents on shift on another queue who hold this queue's skill (`skills`: agent_id -> skills)."""
    gross = defaultdict(lambda: defaultdict(int))
    on_break = defaultdict(lambda: defaultdict(int))
    cross = defaultdict(lambda: defaultdict(int))
    step = timedelta(minutes=grain_min)
    skills = skills or {}
    for r in sched.itertuples(index=False):
        for t in grid:
            if r.segment_start_utc <= t < r.segment_end_utc:
                gross[r.queue][t] += 1
                for q in skills.get(r.agent_id, ()):
                    if q != r.queue:
                        cross[q][t] += 1
                if r.break_minutes and r.break_start_utc < t + step and t < r.break_start_utc + timedelta(minutes=int(r.break_minutes)):
                    on_break[r.queue][t] += 1
    return gross, on_break, cross


def evaluate(req: pd.DataFrame, sched: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> dict:
    sched = _parse(sched)
    grain = cfg["interval_minutes"]
    grid = sorted(set(req["interval_start_utc"]))
    gross, on_break, cross = coverage(sched, grid, grain, {a.agent_id: a.skills for a in agents})
